package asia.aaii.sukhapanya;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
  int green=0xff0c573d,ink=0xff173c2d,bg=0xffeef5ed; LinearLayout root; int correct=0,total=0;
  String[] titles={"တိုင်းရင်းဆေးပညာ အခြေခံ","ဆေးကျမ်း ဖတ်ရှုနည်း","ဆေးဖက်ဝင်အပင်အမည်စနစ်","Research Evidence","Herb–Drug Interaction","ဆေးအရည်အသွေး","အထူးသတိပြုရန် လူအုပ်စုများ","ဘေးထွက်ဖြစ်ရပ် စောင့်ကြည့်မှု","Knowledge Graph","AI ကျမ်းကိုးကား","Research Ethics","Clinical Referral"};
  String[] plants={"Kin-mun-gyin|Acacia concinna","Ma-ya-gyi|Adhatoda vasica","Kyet-thun-ni|Allium cepa","Sha-zaung-let-pat|Aloe vera","Padegaw-gyi|Alpinia galanga","Nanat|Ananas sativus","Say-gha-gyi|Andrographis paniculata","Aw-za|Annona squamosa","Kun-thee-pin|Areca catechu","Zaung-ya|Averrhoa carambola","Tama|Azadirachta indica","Leik-su-shwe|Barleria prionitis","Gin-beik-ni|Basella rubra","Phone-ma-thein|Blumea balsamifera","Htan|Borassus flabellifer","Thin-baw-ma-hnyo|Catharanthus roseus","Thinbaw-mezali|Cassia alata","Ngu|Cassia fistula","Na-lin-gyaw|Cinnamomum obtusifolium","Nga-yant-pa-htu|Clerodendron siphonanthus","Ohn|Cocos nucifera","Ziyar-ywet-tu|Coleus aromaticus","Kadet|Crataeva religiosa","Ko-yan-gyi|Crinum asiaticum","Mye-sa-myet|Cynodon dactylon","Gway-dauk|Dregea volubilis","Kyeik-hman|Eclipta alba","Kywe-kyaung-hmin-hsay|Euphorbia hirta","Sha-zaung-thin-ga-nate|Euphorbia splendens","Yin-khat-kyi|Gardenia coronaria","Si-mee-dauk|Gloriosa superba","Ma-nhyo-lone|Gomphrena globosa","Sin-hna-maung|Heliotropium indicum"};
  public void onCreate(Bundle b){super.onCreate(b);home();}
  GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(22);return d;}
  void page(String title){ ScrollView s=new ScrollView(this);s.setBackgroundColor(bg);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,26,20,30);s.addView(root);setContentView(s);text("🌿 Sukha Panya",19,green,true);text(title,24,ink,true);text("ပညာရေးနှင့် သုတေသနအတွက်သာ • Not medical advice",12,0xff566e62,false);}
  void text(String t,int sp,int color,boolean bold){TextView v=new TextView(this);v.setText(t);v.setTextSize(sp);v.setTextColor(color);v.setPadding(12,13,12,13);if(bold)v.setTypeface(null,1);root.addView(v);}
  void button(String t,Runnable r){Button b=new Button(this);b.setText(t);b.setAllCaps(false);b.setTextColor(-1);b.setBackground(shape(green));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,8,0,8);root.addView(b,p);b.setOnClickListener(v->r.run());}
  void back(){button("← ပင်မစာမျက်နှာ",this::home);}
  void home(){page("တိုင်းရင်းဆေးပညာ");text("Learn • Research • Preserve",16,green,true);button("🌿 ဆေးဖက်ဝင်အပင်များ",this::plantList);button("📚 သင်ခန်းစာများ",this::lessons);button("📝 Quiz / Progress",this::quiz);button("🔬 Research Library",this::research);button("🛡 ဘေးကင်းရေး",this::safety);button("🏅 သင်ယူမှု မှတ်တမ်း",this::progress);button("⚙ Settings",this::settings);}
  void plantList(){page("ဆေးပင် ၃၃ မျိုး");back();for(int i=0;i<plants.length;i++){final int j=i;button("🌱 "+plants[i].replace("|","  •  "),()->detail(j));}}
  void detail(int i){page("ဆေးပင် အသေးစိတ်");back();String[] p=plants[i].split("\\|");text(p[0],23,green,true);text("Scientific name: "+p[1],17,ink,false);text("Reference: Medicinal Plants of Myanmar — Department of Traditional Medicine. Botanical identity needs independent review.",14,ink,false);text("ကုသနိုင်မှု၊ ဆေးပမာဏနှင့် အန္တရာယ်ကင်းမှုကို သက်သေမစိစစ်ရသေးပါ။ မိမိဘာသာ ဆေးအဖြစ် မသုံးပါနှင့်။",16,0xffad4733,true);}
  void lessons(){page("သင်ခန်းစာ ၁၂ ခန်း");back();for(int i=0;i<titles.length;i++){final int j=i;button((i+1)+". "+titles[i],()->lesson(j));}}
  void lesson(int i){page("သင်ခန်းစာ "+(i+1));back();text(titles[i],23,green,true);text("ကျမ်းကိုးကား၊ ရိုးရာအသုံးပြုမှုနှင့် လက်တွေ့ သိပ္ပံသက်သေကို ခွဲခြားလေ့လာရန် အရေးကြီးသည်။ အပင်မျိုးစိတ်၊ ဆေးအရည်အသွေး၊ ဘေးထွက်အန္တရာယ်နှင့် မသေချာမှုကို စိစစ်ပါ။",17,ink,false);text("Sources: WHO Traditional Medicine Strategy; Medicinal Plants of Myanmar; NIH NCCIH",14,ink,false);button("သင်ခန်းစာ Quiz →",this::quiz);}
  void quiz(){page("Quiz");back();String question="ကျမ်းတစ်ခုတွင် ရိုးရာအသုံးပြုမှုဖော်ပြထားခြင်းသည် ကုသနိုင်ကြောင်း သက်သေဖြစ်သလား။";text(question,18,ink,true);String[] opts={"ဖြစ်သည်","သိပ္ပံနည်းကျ ထပ်မံစိစစ်ရန် လိုအပ်သည်","ဆေးအားလုံးအတွက် မှန်ကန်သည်"};RadioGroup g=new RadioGroup(this);root.addView(g);for(int i=0;i<opts.length;i++){RadioButton v=new RadioButton(this);v.setId(100+i);v.setText(opts[i]);v.setTextSize(16);g.addView(v);}button("အဖြေစစ်ရန်",()->{int n=g.getCheckedRadioButtonId();if(n<0){Toast.makeText(this,"အဖြေတစ်ခုရွေးပါ",0).show();return;}total++;if(n==101)correct++;getPreferences(0).edit().putInt("correct",correct).putInt("total",total).apply();new AlertDialog.Builder(this).setTitle(n==101?"မှန်ကန်ပါသည်":"ထပ်လေ့လာကြည့်ပါ").setMessage("ရိုးရာအသုံးပြုမှုသည် ထိရောက်မှုသက်သေ မဟုတ်ပါ။").setPositiveButton("OK",(d,w)->progress()).show();});}
  void research(){page("World Research Library");back();text("1. Medicinal Plants of Myanmar — Ministry of Health",17,ink,true);text("2. WHO Global Traditional Medicine Strategy 2025–2034",17,ink,true);text("3. NIH NCCIH Herbs at a Glance",17,ink,true);text("Scientific reviews and clinical claims require source verification. No automatic prescriptions.",15,ink,false);}
  void safety(){page("Herbal Safety Center");back();text("⚠ တိုင်းရင်းဆေးနှင့် ခေတ်မီဆေးများ အပြန်အလှန်သက်ရောက်နိုင်သည်။",18,0xffa83f2a,true);text("ကိုယ်ဝန်ဆောင်၊ ကလေး၊ သက်ကြီးရွယ်အို၊ နာတာရှည်ရောဂါရှိသူများအတွက် အထူးစိစစ်ရန် လိုအပ်သည်။",17,ink,false);text("အသက်ရှူခက်ခဲခြင်း၊ ရင်ဘတ်အောင့်ခြင်း၊ သတိလစ်ခြင်းစသည့် အရေးပေါ်လက္ခဏာရှိလျှင် ဆေးရုံအကူအညီ ရယူပါ။",17,ink,true);}
  void progress(){page("Progress");back();int a=getPreferences(0).getInt("correct",0),b=getPreferences(0).getInt("total",0);text("Quiz မှန်ကန်မှု: "+a+" / "+b,23,green,true);text("ဒီမှတ်တမ်းက Study Quiz အတွက်သာဖြစ်သည်။ ဆရာဝန်လက်မှတ် သို့မဟုတ် Medical Qualification မဟုတ်ပါ။",15,ink,false);}
  void settings(){page("Settings");back();text("Offline Study App • Myanmar Unicode • Version 8.0",17,ink,false);button("Quiz Progress ရှင်းရန်",()->{getPreferences(0).edit().clear().apply();correct=0;total=0;progress();});}
}